        "episodes": [
          {
            "id": 3868551,
            "episodeNumber": 1,
            "name": "Moth to a Flame",
            "airDate": "2023-02-17",
            "runtime": 55,
            "overview": "While Jo is a struggling writer with a casual job, Alice has achieved her childhood dream as a world-renowned cellist. Struck by Alice’s coolness towards her, Jo is compelled to revisit the past, recalling their arrival at Silver Creek.",
            "stillPath": "/4tMGTrn1CNaNc21QIfrDM3D8iZM.jpg"
          },
          {
            "id": 3868556,
            "episodeNumber": 2,
            "name": "The Worst",
            "airDate": "2023-02-17",
            "runtime": 56,
            "overview": "Riding high on adrenaline from Portia’s approval, Jo lands herself in trouble with a furious Miss Lacey. Alice clings to whatever crumbs of friendship Jo offers her.",
            "stillPath": "/k0qIeSOkfjPqICQyYfkHLjlL1qp.jpg"
          },
          {
            "id": 3868557,
            "episodeNumber": 3,
            "name": "Exeat",
            "airDate": "2023-02-17",
            "runtime": 53,
            "overview": "Red House is reunited in the present day at the funeral of their peer Emma, one of the few girls they all remember warmly despite their different memories of Silver Creek. Jo attempts to forge a healthier path for herself.",
            "stillPath": "/tsEJEROTQN7sAnsRVWoY4yjoEN5.jpg"
          },
          {
            "id": 3868558,
            "episodeNumber": 4,
            "name": "Wilderness",
            "airDate": "2023-02-17",
            "runtime": 51,
            "overview": "Fifteen-year-old Jo tries to rally the girls into standing up to Portia. Presently, Jo and Portia share a rare and honest conversation about their time at Silver Creek. Jo decides to face her past head-on.",
            "stillPath": "/IaEJnxlooRm3eJ3S7Jhy0ab8bE.jpg"
          }
        ]
